  const auto observations=make_observations();
  std::vector<std::optional<PnmlDocument>> documents(fixtures.size());
  PnmlImportOptions import; import.infer_initial_marking=false; import.infer_final_marking=false; import.require_workflow_boundaries=false;
  for (const auto& fixture:fixtures) {
    bool rejected=false;
    try { documents[fixture.index]=parse_pnml_document(fixture.xml,import); }
    catch (const std::runtime_error&) { rejected=true; }
    assert(rejected==!fixture.imported);
  }
  for (const auto& expected:observations) {
    const auto& document=*documents[expected.index];
    EventLog log; Trace trace; trace.case_id="owned-weighted";
    for (const auto& activity:expected.activities) {
      Event event; event.activity=activity; event.activity_state=FirstClassAttributeState::kPresent;
      event.activity_source_key="concept:name";
      event.activity_attribute=EventAttribute{"concept:name",activity,AttributeKind::kString,false};
      trace.events.push_back(std::move(event));
    }
    log.traces.push_back(std::move(trace));
    auto options=tools::pnml_replay_options(document,{});
    options.stop_immediately_unfit=expected.stop; options.cleaning_token_flood=expected.clean;
    const auto results=replay_token_traces(log,document.net,options); assert(results.size()==1);
    const auto& result=results.front();
    assert(result.trace_is_fit==expected.fit && result.trace_fitness==expected.fitness);
    assert(result.produced==TokenInteger(expected.counts[0]) && result.consumed==TokenInteger(expected.counts[1]));
    assert(result.missing==TokenInteger(expected.counts[2]) && result.remaining==TokenInteger(expected.counts[3]));
    const auto names=[&](const auto& ids) { std::vector<std::string> out; for (const auto id:ids) out.push_back(document.transition_ids[id]); return out; };
    assert(names(result.activated_transitions)==expected.activated && names(result.transitions_with_problems)==expected.problems);
    auto enabled=names(result.enabled_transitions);auto expected_enabled=expected.enabled;
    std::sort(enabled.begin(),enabled.end());std::sort(expected_enabled.begin(),expected_enabled.end());
    assert(enabled==expected_enabled);
    std::map<std::string,TokenInteger> marking,expected_marking;
    assert(result.reached_marking_keys.size()==document.place_ids.size());
    for (std::size_t place=0;place<document.place_ids.size();++place)
      if (result.reached_marking_keys[place]) marking.emplace(document.place_ids[place],result.reached_marking[place]);
    for (const auto& [name,count]:expected.marking) expected_marking.emplace(name,TokenInteger(count));
    assert(marking==expected_marking);
  }
